func parsePrefixSet(args []string) (*api.DefinedSet, error) {
	if len(args) < 1 {
		return nil, fmt.Errorf("empty neighbor set name")
	}
	name := args[0]
	args = args[1:]
	var list []*api.Prefix
	if len(args) > 0 {
		mask := ""
		if len(args) > 1 {
			mask = args[1]
		}
		min, max, err := oc.ParseMaskLength(args[0], mask)
		if err != nil {
			return nil, err
		}
		prefix := &api.Prefix{
			MaskLengthMax: uint32(max),
			MaskLengthMin: uint32(min),
		}
		// CIDR and rtc-prefix forms are unambiguous; pick by which parses.
		if _, perr := netip.ParsePrefix(args[0]); perr == nil {
			prefix.IpPrefix = args[0]
		} else if _, perr := bgp.ParseRTCPrefix(args[0]); perr == nil {
			prefix.RtcPrefix = args[0]
		} else {
			return nil, fmt.Errorf("invalid ip-prefix or rtc-prefix: %s", args[0])
		}
		list = []*api.Prefix{prefix}
	}
	return &api.DefinedSet{
		DefinedType: api.DefinedType_DEFINED_TYPE_PREFIX,
		Name:        name,
		Prefixes:    list,
	}, nil
}

func parseNeighborSet(args []string) (*api.DefinedSet, error) {
	if len(args) < 1 {
		return nil, fmt.Errorf("empty neighbor set name")
	}
	name := args[0]
	args = args[1:]
	list := make([]string, 0, len(args))
	for _, arg := range args {
		// The server checks an entry with a zone, such as fe80::1%eth0.
		if strings.Contains(arg, "%") {
			list = append(list, arg)
			continue
		}
		address := net.ParseIP(arg)
		if address.To4() != nil {
			list = append(list, fmt.Sprintf("%s/32", arg))
		} else if address.To16() != nil {
			list = append(list, fmt.Sprintf("%s/128", arg))
		} else {
			_, _, err := net.ParseCIDR(arg)
			if err != nil {
				return nil, fmt.Errorf("invalid address or prefix: %s\nplease enter ipv4 or ipv6 format", arg)
			}
			list = append(list, arg)
		}
	}
	return &api.DefinedSet{
		DefinedType: api.DefinedType_DEFINED_TYPE_NEIGHBOR,
		Name:        name,
		List:        list,
	}, nil
}

