+}
+
+func (c *SourceASCondition) Evaluate(path *Path, _ *PolicyOptions) bool {
+	if len(c.list) == 0 {
+		return true
+	}
+	if path.GetAsPath() == nil {
+		return false
+	}
+	asn := path.GetSourceAs()
+	matched := slices.Contains(c.list, asn)
+	switch c.option {
+	case MATCH_OPTION_INVERT:
+		return !matched
