+	}
+	if c.community != nil {
+		return c.community.Set()
+	}
+	return nil
+}
+
+func (c *AsPathCommunityCondition) DefinedSets() []DefinedSet {
+	sets := make([]DefinedSet, 0, 2)
+	if c.asPath != nil {
+		sets = append(sets, c.asPath.Set())
+	}
+	if c.community != nil {
+		sets = append(sets, c.community.Set())
+	}
+	return sets
